-- New pilot production ledger only; historical order/pricing functions and rows are unchanged.
begin;
create table public.lab_production_policies(photographer_id uuid primary key references public.photographers(id),version integer not null default 1,policy jsonb not null,updated_at timestamptz not null default now());
create table public.lab_production_assets(id uuid primary key,photographer_id uuid not null references public.photographers(id),kind text not null check(kind in('original','crop','corrected')),job_id uuid,size text check(size in('8x10','5x7')),source_asset_id uuid references public.lab_production_assets(id),filename text not null,storage_key text not null unique,sha256 text not null check(sha256~'^[a-f0-9]{64}$'),byte_size integer not null check(byte_size between 1 and 4000000),width_pixels integer not null check(width_pixels between 1 and 16000),height_pixels integer not null check(height_pixels between 1 and 16000),content_type text not null check(content_type in('image/jpeg','image/png')),created_at timestamptz not null default now(),check(width_pixels::bigint*height_pixels<=100000000));
create table public.lab_production_galleries(id uuid primary key default gen_random_uuid(),photographer_id uuid not null references public.photographers(id),lab_id uuid references public.studio_labs(id),request_id uuid not null,request_payload jsonb not null,document jsonb not null,photo_map jsonb not null,source jsonb not null,token_hash text not null unique check(token_hash~'^[a-f0-9]{64}$'),version integer not null default 1,expires_at timestamptz not null default now()+interval '7 days',revoked_at timestamptz,created_at timestamptz not null default now(),unique(photographer_id,request_id));
create table public.lab_production_jobs(id uuid primary key default gen_random_uuid(),photographer_id uuid not null references public.photographers(id),lab_id uuid references public.studio_labs(id),gallery_id uuid not null references public.lab_production_galleries(id),reference text not null unique,request_id uuid not null,request_payload jsonb not null,receipt_hash text not null unique check(receipt_hash~'^[a-f0-9]{64}$'),receipt_expires_at timestamptz not null default now()+interval '30 days',snapshot jsonb not null,work jsonb not null,status text not null default 'submitted' check(status in('submitted','accepted','in_production','ready','completed')),version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(gallery_id,request_id));
alter table public.lab_production_assets add constraint lab_production_assets_job_fk foreign key(job_id) references public.lab_production_jobs(id);
create table public.lab_production_events(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.lab_production_jobs(id),actor_user_id uuid references auth.users(id),actor_role text not null check(actor_role in('photographer','lab','policy')),request_id uuid not null,request_payload jsonb not null,action text not null,version integer not null,created_at timestamptz not null default now(),unique(job_id,version),unique(actor_user_id,request_id));
create index lab_production_jobs_owner_idx on public.lab_production_jobs(photographer_id,created_at desc,id);
create index lab_production_jobs_lab_idx on public.lab_production_jobs(lab_id,created_at desc,id);
create index lab_production_assets_owner_idx on public.lab_production_assets(photographer_id,created_at desc,id);
create index lab_production_galleries_owner_idx on public.lab_production_galleries(photographer_id,created_at desc,id);
create index lab_production_events_job_idx on public.lab_production_events(job_id,version);

create function public.lab_production_owner(p_user_id uuid,p_owner uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.photographers p where p.id=p_owner and p.user_id=p_user_id)$$;
create function public.lab_production_receiver(p_user_id uuid,p_owner uuid,p_lab uuid) returns boolean language sql stable security definer set search_path='' as $$select case when p_lab is null then public.lab_production_owner(p_user_id,p_owner) else exists(select 1 from public.lab_memberships m where m.lab_id=p_lab and m.user_id=p_user_id and m.active and m.role in('owner','operator')) end$$;
create function public.lab_production_reader(p_user_id uuid,p_owner uuid,p_lab uuid) returns boolean language sql stable security definer set search_path='' as $$select public.lab_production_owner(p_user_id,p_owner) or exists(select 1 from public.lab_memberships m where m.lab_id=p_lab and m.user_id=p_user_id and m.active)$$;

do $$declare t text;begin foreach t in array array['lab_production_policies','lab_production_assets','lab_production_galleries','lab_production_jobs','lab_production_events'] loop execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);execute format('grant select on public.%I to authenticated,service_role',t);end loop;end$$;
create policy production_policies_read on public.lab_production_policies for select to authenticated using(public.lab_production_owner(auth.uid(),photographer_id));
create policy production_galleries_read on public.lab_production_galleries for select to authenticated using(public.lab_production_owner(auth.uid(),photographer_id));
-- Lab APIs project wholesale-only documents. A direct job SELECT must not
-- expose the immutable photographer retail agreement to partner staff.
create policy production_jobs_read on public.lab_production_jobs for select to authenticated using(public.lab_production_owner(auth.uid(),photographer_id));
create function public.lab_production_file_reader(p_user_id uuid,p_job_id uuid,p_source_asset_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.lab_production_jobs j where (j.id=p_job_id or j.snapshot->>'sourceAssetId'=p_source_asset_id::text) and (public.lab_production_owner(p_user_id,j.photographer_id) or (coalesce(auth.jwt()->>'aal','')='aal2' and public.lab_production_reader(p_user_id,j.photographer_id,j.lab_id))))$$;
create policy production_assets_read on public.lab_production_assets for select to authenticated using(public.lab_production_owner(auth.uid(),photographer_id) or public.lab_production_file_reader(auth.uid(),job_id,id));
create policy production_events_read on public.lab_production_events for select to authenticated using(public.lab_production_file_reader(auth.uid(),job_id,null));

create function public.protect_lab_production() returns trigger language plpgsql set search_path='' as $$begin
 if tg_op='DELETE' or tg_table_name in('lab_production_assets','lab_production_events') then raise exception 'PRODUCTION_IMMUTABLE' using errcode='42501';end if;
 if tg_table_name='lab_production_jobs' then
 if row(new.id,new.photographer_id,new.lab_id,new.gallery_id,new.reference,new.request_id,new.request_payload,new.receipt_hash,new.receipt_expires_at,new.snapshot,new.created_at) is distinct from row(old.id,old.photographer_id,old.lab_id,old.gallery_id,old.reference,old.request_id,old.request_payload,old.receipt_hash,old.receipt_expires_at,old.snapshot,old.created_at) then raise exception 'PRODUCTION_IMMUTABLE' using errcode='42501';end if;
 elsif tg_table_name='lab_production_galleries' then
 if row(new.id,new.photographer_id,new.lab_id,new.request_id,new.request_payload,new.document,new.photo_map,new.source,new.created_at) is distinct from row(old.id,old.photographer_id,old.lab_id,old.request_id,old.request_payload,old.document,old.photo_map,old.source,old.created_at) then raise exception 'PRODUCTION_IMMUTABLE' using errcode='42501';end if;end if;return new;end$$;
create trigger production_assets_immutable before update or delete on public.lab_production_assets for each row execute function public.protect_lab_production();
create trigger production_events_immutable before update or delete on public.lab_production_events for each row execute function public.protect_lab_production();
create trigger production_jobs_snapshot before update or delete on public.lab_production_jobs for each row execute function public.protect_lab_production();
create trigger production_galleries_snapshot before update or delete on public.lab_production_galleries for each row execute function public.protect_lab_production();

create function public.lab_production_policy_valid(p jsonb) returns boolean language sql immutable set search_path='' as $$select jsonb_typeof(p)='object' and (select count(*) from jsonb_object_keys(p))=3 and jsonb_typeof(p->'autoApprove')='boolean' and p->>'cropResponsibility' in('photographer','lab') and jsonb_typeof(p->'labColourCorrection')='boolean'$$;
create function public.save_lab_production_policy(p_user_id uuid,p_expected_version integer,p_policy jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare owner_id uuid;r public.lab_production_policies%rowtype;begin
 if p_expected_version is null or p_expected_version<1 or public.lab_production_policy_valid(p_policy) is distinct from true then raise exception 'PRODUCTION_INVALID' using errcode='22023';end if;
 select id into owner_id from public.photographers where user_id=p_user_id;if owner_id is null then raise exception 'PRODUCTION_FORBIDDEN' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('production-policy:'||owner_id::text,20261016));select * into r from public.lab_production_policies where photographer_id=owner_id for update;
 if found then if r.version<>p_expected_version then raise exception 'PRODUCTION_VERSION_CONFLICT' using errcode='PT409';end if;update public.lab_production_policies set policy=p_policy,version=version+1,updated_at=now() where photographer_id=owner_id returning * into r;
 else if p_expected_version<>1 then raise exception 'PRODUCTION_VERSION_CONFLICT' using errcode='PT409';end if;insert into public.lab_production_policies(photographer_id,version,policy) values(owner_id,2,p_policy) returning * into r;end if;return to_jsonb(r);end$$;

create function public.register_lab_production_asset(p_user_id uuid,p_document jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare owner_id uuid;j public.lab_production_jobs%rowtype;a public.lab_production_assets%rowtype;s public.lab_production_assets%rowtype;begin
 if p_document is null or jsonb_typeof(p_document)<>'object' or octet_length(p_document::text)>8000 or exists(select 1 from jsonb_object_keys(p_document) k where k not in('id','kind','jobId','size','sourceAssetId','filename','storageKey','sha256','byteSize','widthPixels','heightPixels','contentType')) or p_document->>'kind' is null or p_document->>'kind' not in('original','crop','corrected') or (select count(*) from jsonb_object_keys(p_document))<>12 or exists(select 1 from unnest(array['byteSize','widthPixels','heightPixels']) k where jsonb_typeof(p_document->k) is distinct from 'number' or (p_document->>k)::numeric<>trunc((p_document->>k)::numeric)) or p_document->>'filename' is null or length(p_document->>'filename') not between 1 and 200 or p_document->>'filename'~'[[:cntrl:]]' or coalesce(p_document->>'storageKey','') !~ '^[a-f0-9-]+/[a-f0-9-]+[.](jpg|png)$' or jsonb_typeof(p_document->'sha256') is distinct from 'string' or coalesce(p_document->>'sha256','') !~ '^[a-f0-9]{64}$' then raise exception 'PRODUCTION_INVALID_ASSET' using errcode='22023';end if;
 if p_document->>'kind'='original' then
 select id into owner_id from public.photographers where user_id=p_user_id;if owner_id is null or p_document->>'jobId' is not null or p_document->>'size' is not null or p_document->>'sourceAssetId' is not null then raise exception 'PRODUCTION_FORBIDDEN' using errcode='42501';end if;
 else
 select * into j from public.lab_production_jobs where id=(p_document->>'jobId')::uuid for update;if not found then raise exception 'PRODUCTION_NOT_FOUND' using errcode='42501';end if;
 owner_id:=j.photographer_id;
 if p_document->>'kind'='corrected' then
 if not public.lab_production_receiver(p_user_id,j.photographer_id,j.lab_id) or j.snapshot#>>'{policy,labColourCorrection}' is distinct from 'true' or j.status<>'accepted' then raise exception 'PRODUCTION_FORBIDDEN' using errcode='42501';end if;
 select * into s from public.lab_production_assets where id=(p_document->>'sourceAssetId')::uuid;
 if s.job_id is distinct from j.id or s.kind<>'crop' or s.size is distinct from p_document->>'size' or (j.work#>>array['lines',case s.size when '8x10' then '0' else '1' end,'cropAssetId']) is distinct from s.id::text or j.work#>>array['lines',case s.size when '8x10' then '0' else '1' end,'cropApproved'] is distinct from 'true' or s.width_pixels<>(p_document->>'widthPixels')::integer or s.height_pixels<>(p_document->>'heightPixels')::integer then raise exception 'PRODUCTION_STALE_RENDER' using errcode='PT409';end if;
 else
 if not(public.lab_production_owner(p_user_id,j.photographer_id) and j.snapshot#>>'{policy,cropResponsibility}'='photographer') and not(public.lab_production_receiver(p_user_id,j.photographer_id,j.lab_id) and j.snapshot#>>'{policy,cropResponsibility}'='lab') then raise exception 'PRODUCTION_FORBIDDEN' using errcode='42501';end if;
 if p_document->>'sourceAssetId' is distinct from j.snapshot->>'sourceAssetId' or p_document->>'size' is null or p_document->>'size' not in('8x10','5x7') or j.status not in('submitted','accepted') then raise exception 'PRODUCTION_STALE_RENDER' using errcode='PT409';end if;
 end if;end if;
 if p_document->>'contentType' is null or p_document->>'contentType' not in('image/jpeg','image/png') or right(p_document->>'storageKey',4) is distinct from (case p_document->>'contentType' when 'image/png' then '.png' else '.jpg' end) then raise exception 'PRODUCTION_INVALID_ASSET' using errcode='22023';end if;
 if split_part(p_document->>'storageKey','/',1)<>owner_id::text or split_part(split_part(p_document->>'storageKey','/',2),'.',1) is distinct from p_document->>'id' then raise exception 'PRODUCTION_INVALID_ASSET' using errcode='22023';end if;
 if p_document->>'kind'<>'original' and ((p_document->>'widthPixels')::integer<>(case p_document->>'size' when '8x10' then 2400 else 1500 end) or (p_document->>'heightPixels')::integer<>(case p_document->>'size' when '8x10' then 3000 else 2100 end)) then raise exception 'PRODUCTION_INVALID_ASSET' using errcode='22023';end if;
 select * into a from public.lab_production_assets where id=(p_document->>'id')::uuid;if found then
 if row(a.photographer_id,a.kind,a.job_id,a.size,a.source_asset_id,a.filename,a.storage_key,a.sha256,a.byte_size,a.width_pixels,a.height_pixels,a.content_type) is distinct from row(owner_id,p_document->>'kind',(p_document->>'jobId')::uuid,p_document->>'size',(p_document->>'sourceAssetId')::uuid,p_document->>'filename',p_document->>'storageKey',p_document->>'sha256',(p_document->>'byteSize')::integer,(p_document->>'widthPixels')::integer,(p_document->>'heightPixels')::integer,p_document->>'contentType') then raise exception 'PRODUCTION_REQUEST_CONFLICT' using errcode='PT409';end if;return to_jsonb(a);end if;
 perform pg_advisory_xact_lock(hashtextextended('production-assets:'||owner_id::text,20261016));if(select count(*) from public.lab_production_assets where photographer_id=owner_id)>=2000 then raise exception 'PRODUCTION_LIMIT' using errcode='22023';end if;
 insert into public.lab_production_assets(id,photographer_id,kind,job_id,size,source_asset_id,filename,storage_key,sha256,byte_size,width_pixels,height_pixels,content_type) values((p_document->>'id')::uuid,owner_id,p_document->>'kind',(p_document->>'jobId')::uuid,p_document->>'size',(p_document->>'sourceAssetId')::uuid,p_document->>'filename',p_document->>'storageKey',p_document->>'sha256',(p_document->>'byteSize')::integer,(p_document->>'widthPixels')::integer,(p_document->>'heightPixels')::integer,p_document->>'contentType') returning * into a;return to_jsonb(a);end$$;

create function public.create_lab_production_gallery(p_user_id uuid,p_request_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare owner_id uuid;s public.in_house_price_sheets%rowtype;g public.lab_production_galleries%rowtype;p public.lab_production_policies%rowtype;e jsonb;photos jsonb:='[]';mapping jsonb:='{}';a public.lab_production_assets%rowtype;aid text;pid uuid;lab public.studio_labs%rowtype;c public.studio_lab_catalog%rowtype;lab_id uuid;target_label text;cost bigint:=0;policy jsonb;begin
 select id into owner_id from public.photographers where user_id=p_user_id;if owner_id is null or p_request_id is null then raise exception 'PRODUCTION_FORBIDDEN' using errcode='42501';end if;
 if p_payload is null or jsonb_typeof(p_payload)<>'object' or exists(select 1 from jsonb_object_keys(p_payload) k where k not in('sheetId','expectedSheetVersion','entryId','name','assetIds','tokenHash','target')) or jsonb_typeof(p_payload->'expectedSheetVersion') is distinct from 'number' or (p_payload->>'expectedSheetVersion')::numeric<>trunc((p_payload->>'expectedSheetVersion')::numeric) or (p_payload->>'expectedSheetVersion')::numeric<1 or jsonb_typeof(p_payload->'target') is distinct from 'object' or coalesce(p_payload->>'name','')='' or length(p_payload->>'name')>100 or p_payload->>'name'~'[[:cntrl:]]' or coalesce(p_payload->>'tokenHash','') !~ '^[a-f0-9]{64}$' or jsonb_typeof(p_payload->'assetIds') is distinct from 'array' or jsonb_array_length(p_payload->'assetIds') not between 1 and 20 then raise exception 'PRODUCTION_INVALID' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('production-owner:'||owner_id::text,20261016));select * into g from public.lab_production_galleries where photographer_id=owner_id and request_id=p_request_id;
 if found then if g.request_payload is distinct from p_payload then raise exception 'PRODUCTION_REQUEST_CONFLICT' using errcode='PT409';end if;return to_jsonb(g)||jsonb_build_object('replayed',true);end if;
 select * into s from public.in_house_price_sheets where id=(p_payload->>'sheetId')::uuid and photographer_id=owner_id for share;if not found then raise exception 'PRODUCTION_NOT_FOUND' using errcode='42501';end if;if s.version is distinct from (p_payload->>'expectedSheetVersion')::integer then raise exception 'PRODUCTION_VERSION_CONFLICT' using errcode='PT409';end if;
 select value into e from jsonb_array_elements(s.document->'entries') where value->>'id'=p_payload->>'entryId';
 if e->'active' is distinct from 'true'::jsonb or e->>'section' is distinct from 'package' or jsonb_typeof(e->'retailCents') is distinct from 'number' or (e->>'retailCents')::numeric<>trunc((e->>'retailCents')::numeric) or coalesce((e->>'retailCents')::numeric,0) not between 1 and 100000000 or jsonb_typeof(e->'contents') is distinct from 'array' or jsonb_array_length(e->'contents')<>2 or not(e->'contents' @> '[{"name":"8x10 Lustre","qty":1},{"name":"5x7 Lustre","qty":2}]'::jsonb) or exists(select 1 from jsonb_array_elements(e->'contents') i where jsonb_typeof(i)<>'object' or (select count(*) from jsonb_object_keys(i))<>2) then raise exception 'PRODUCTION_OFFER_UNAVAILABLE' using errcode='PT409';end if;
 select * into p from public.lab_production_policies where photographer_id=owner_id for share;policy:=coalesce(p.policy,'{"autoApprove":false,"cropResponsibility":"photographer","labColourCorrection":false}'::jsonb);
 if p_payload#>>'{target,kind}'='in_house' then if p_payload->'target'<>'{"kind":"in_house"}'::jsonb then raise exception 'PRODUCTION_INVALID' using errcode='22023';end if;target_label:=s.studio_name;
 elsif p_payload#>>'{target,kind}'='partner_lab' then
 if (select count(*) from jsonb_object_keys(p_payload->'target'))<>4 or exists(select 1 from jsonb_object_keys(p_payload->'target') k where k not in('kind','labId','product8x10Id','product5x7Id')) or p_payload#>>'{target,labId}' is null or p_payload#>>'{target,product8x10Id}' is null or p_payload#>>'{target,product5x7Id}' is null or p_payload#>>'{target,product8x10Id}'=p_payload#>>'{target,product5x7Id}' then raise exception 'PRODUCTION_INVALID' using errcode='22023';end if;lab_id:=(p_payload#>>'{target,labId}')::uuid;select * into lab from public.studio_labs where id=lab_id for share;if not found or lab.status<>'active' or not lab.intake_enabled or not lab.catalog_verified or lab.currency<>s.currency then raise exception 'PRODUCTION_LAB_NOT_READY' using errcode='PT409';end if;target_label:=lab.name;
 for aid in select unnest(array[p_payload#>>'{target,product8x10Id}',p_payload#>>'{target,product5x7Id}']) loop
 select * into c from public.studio_lab_catalog where id=aid::uuid and studio_lab_catalog.lab_id=lab.id for share;
 if not found or not c.active or not c.verified or c.sku is null or c.cost_cents is null or c.cost_source<>'lab_confirmed' or c.category<>'prints' or c.prints_per_unit<>1 or c.finish<>'Lustre' or c.width_inches<>(case when aid=p_payload#>>'{target,product8x10Id}' then 8 else 5 end) or c.height_inches<>(case when aid=p_payload#>>'{target,product8x10Id}' then 10 else 7 end) then raise exception 'PRODUCTION_LAB_NOT_READY' using errcode='PT409';end if;cost:=cost+c.cost_cents*case when aid=p_payload#>>'{target,product8x10Id}' then 1 else 2 end;end loop;
 else raise exception 'PRODUCTION_INVALID' using errcode='22023';end if;
 for aid in select jsonb_array_elements_text(p_payload->'assetIds') loop
 if mapping @> jsonb_build_object(aid,aid) then raise exception 'PRODUCTION_INVALID' using errcode='22023';end if;
 select * into a from public.lab_production_assets where id=aid::uuid and photographer_id=owner_id and kind='original';if not found then raise exception 'PRODUCTION_NOT_FOUND' using errcode='42501';end if;
 if a.width_pixels<1600 or a.height_pixels<2000 then raise exception 'PRODUCTION_SOURCE_DETAIL' using errcode='22023';end if;
 if exists(select 1 from jsonb_each_text(mapping) m where m.value=aid) then raise exception 'PRODUCTION_INVALID' using errcode='22023';end if;
 pid:=gen_random_uuid();mapping:=mapping||jsonb_build_object(pid::text,a.id);photos:=photos||jsonb_build_array(jsonb_build_object('id',pid,'filename',a.filename,'widthPixels',a.width_pixels,'heightPixels',a.height_pixels));end loop;
 if(select count(*) from public.lab_production_galleries where photographer_id=owner_id)>=30 then raise exception 'PRODUCTION_LIMIT' using errcode='22023';end if;
 insert into public.lab_production_galleries(photographer_id,lab_id,request_id,request_payload,document,photo_map,source,token_hash) values(owner_id,lab_id,p_request_id,p_payload,jsonb_build_object('name',p_payload->>'name','studioName',s.studio_name,'currency',s.currency,'offer',jsonb_build_object('id',gen_random_uuid(),'name',e->>'name','retailCents',e->'retailCents','contents',e->'contents'),'policy',policy,'photos',photos,'targetLabel',target_label),mapping,jsonb_build_object('sheetId',s.id,'sheetVersion',s.version,'entryId',e->>'id','sourceHash',s.source_hash,'target',p_payload->'target','wholesalePackageMinor',cost),p_payload->>'tokenHash') returning * into g;return to_jsonb(g)||jsonb_build_object('replayed',false);end$$;

create function public.manage_lab_production_gallery(p_user_id uuid,p_gallery_id uuid,p_expected_version integer,p_action text,p_token_hash text) returns jsonb language plpgsql security definer set search_path='' as $$declare g public.lab_production_galleries%rowtype;begin
 if p_expected_version is null or p_expected_version<1 or p_action is null or p_action not in('rotate','revoke') or p_action='rotate' and coalesce(p_token_hash,'')!~'^[a-f0-9]{64}$' or p_action='revoke' and p_token_hash is not null then raise exception 'PRODUCTION_INVALID' using errcode='22023';end if;
 select * into g from public.lab_production_galleries where id=p_gallery_id for update;if not found or not public.lab_production_owner(p_user_id,g.photographer_id) then raise exception 'PRODUCTION_NOT_FOUND' using errcode='42501';end if;
 if g.version=p_expected_version+1 and ((p_action='revoke' and g.revoked_at is not null) or(p_action='rotate' and g.token_hash=p_token_hash and g.revoked_at is null)) then return to_jsonb(g)||jsonb_build_object('replayed',true);end if;
 if g.version<>p_expected_version then raise exception 'PRODUCTION_VERSION_CONFLICT' using errcode='PT409';end if;
 if p_action='rotate' then if p_token_hash=g.token_hash then raise exception 'PRODUCTION_REQUEST_CONFLICT' using errcode='PT409';end if;update public.lab_production_galleries set token_hash=p_token_hash,expires_at=now()+interval '7 days',revoked_at=null,version=version+1 where id=g.id returning * into g;
 else update public.lab_production_galleries set revoked_at=now(),version=version+1 where id=g.id returning * into g;end if;return to_jsonb(g)||jsonb_build_object('replayed',false);end$$;
create function public.read_lab_production_gallery(p_gallery_id uuid,p_token_hash text) returns jsonb language plpgsql security definer set search_path='' as $$declare g public.lab_production_galleries%rowtype;begin select * into g from public.lab_production_galleries where id=p_gallery_id and token_hash=p_token_hash and revoked_at is null and expires_at>now();if not found then raise exception 'PRODUCTION_NOT_FOUND' using errcode='42501';end if;return g.document||jsonb_build_object('id',g.id,'version',g.version,'expiresAt',g.expires_at,'revokedAt',g.revoked_at,'createdAt',g.created_at);end$$;
create function public.read_lab_production_photo(p_gallery_id uuid,p_token_hash text,p_photo_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare g public.lab_production_galleries%rowtype;a public.lab_production_assets%rowtype;begin select * into g from public.lab_production_galleries where id=p_gallery_id and token_hash=p_token_hash and revoked_at is null and expires_at>now();if not found then raise exception 'PRODUCTION_NOT_FOUND' using errcode='42501';end if;select * into a from public.lab_production_assets where id=(g.photo_map->>p_photo_id::text)::uuid and photographer_id=g.photographer_id and kind='original';if not found then raise exception 'PRODUCTION_NOT_FOUND' using errcode='42501';end if;return to_jsonb(a);end$$;

create function public.lab_production_holds(p_job public.lab_production_jobs) returns jsonb language plpgsql stable set search_path='' as $$declare holds jsonb:='[]';l jsonb;begin
 if p_job.work->>'photographerApproved' is distinct from 'true' then holds:=holds||'"photographer_approval"'::jsonb;end if;
 for l in select value from jsonb_array_elements(p_job.work->'lines') loop
 if l->>'cropApproved' is distinct from 'true' or l->>'cropAssetId' is null then holds:=holds||to_jsonb('crop_'||(l->>'size'));end if;
 if p_job.snapshot#>>'{policy,labColourCorrection}'='true' and l->>'colourAssetId' is null then holds:=holds||to_jsonb('colour_'||(l->>'size'));end if;
 if l->>'finalReviewedAt' is null then holds:=holds||to_jsonb('final_review_'||(l->>'size'));end if;end loop;return holds;end$$;
create function public.lab_production_receipt(p_job public.lab_production_jobs) returns jsonb language sql stable set search_path='' as $$select (p_job.snapshot-'sourceAssetId'-'source')||jsonb_build_object('id',p_job.id,'reference',p_job.reference,'version',p_job.version,'status',p_job.status,'holds',public.lab_production_holds(p_job),'createdAt',p_job.created_at,'updatedAt',p_job.updated_at,'events',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'action',e.action,'actorRole',e.actor_role,'version',e.version,'createdAt',e.created_at) order by e.version) from public.lab_production_events e where e.job_id=p_job.id),'[]'::jsonb))$$;
create function public.submit_lab_production_order(p_gallery_id uuid,p_token_hash text,p_request_id uuid,p_receipt_hash text,p_photo_id uuid,p_quantity integer) returns jsonb language plpgsql security definer set search_path='' as $$declare g public.lab_production_galleries%rowtype;j public.lab_production_jobs%rowtype;payload jsonb;aid uuid;jid uuid;auto boolean;begin
 if p_request_id is null or p_quantity is null or p_quantity not between 1 and 10 or coalesce(p_receipt_hash,'')!~'^[a-f0-9]{64}$' then raise exception 'PRODUCTION_INVALID' using errcode='22023';end if;
 select * into g from public.lab_production_galleries where id=p_gallery_id and token_hash=p_token_hash and revoked_at is null and expires_at>now() for update;if not found then raise exception 'PRODUCTION_NOT_FOUND' using errcode='42501';end if;
 payload:=jsonb_build_object('tokenHash',p_token_hash,'receiptHash',p_receipt_hash,'photoId',p_photo_id,'quantity',p_quantity);select * into j from public.lab_production_jobs where gallery_id=g.id and request_id=p_request_id;if found then if j.request_payload is distinct from payload then raise exception 'PRODUCTION_REQUEST_CONFLICT' using errcode='PT409';end if;return public.lab_production_receipt(j)||jsonb_build_object('replayed',true);end if;
 if g.lab_id is not null and not exists(select 1 from public.studio_labs l where l.id=g.lab_id and l.status='active' and l.intake_enabled and l.catalog_verified) then raise exception 'PRODUCTION_LAB_NOT_READY' using errcode='PT409';end if;
 aid:=(g.photo_map->>p_photo_id::text)::uuid;if aid is null then raise exception 'PRODUCTION_NOT_FOUND' using errcode='42501';end if;
 if(select count(*) from public.lab_production_jobs where gallery_id=g.id)>=20 then raise exception 'PRODUCTION_LIMIT' using errcode='22023';end if;
 auto:=(g.document#>>'{policy,autoApprove}')::boolean;jid:=gen_random_uuid();
 insert into public.lab_production_jobs(id,photographer_id,lab_id,gallery_id,reference,request_id,request_payload,receipt_hash,snapshot,work) values(jid,g.photographer_id,g.lab_id,g.id,'PROOF-'||upper(replace(jid::text,'-','')),p_request_id,payload,p_receipt_hash,(g.document-'photos'-'name')||jsonb_build_object('sourceAssetId',aid,'source',g.source,'quantity',p_quantity,'subtotalMinor',(g.document#>>'{offer,retailCents}')::bigint*p_quantity,'testOnly',true,'payment','test_no_payment','printAllowed',false),jsonb_build_object('photographerApproved',auto,'photographerApprovedAt',case when auto then now() else null end,'lines',jsonb_build_array(jsonb_build_object('size','8x10','quantity',p_quantity,'widthInches',8,'heightInches',10,'cropApproved',false),jsonb_build_object('size','5x7','quantity',p_quantity*2,'widthInches',5,'heightInches',7,'cropApproved',false)))) returning * into j;
 insert into public.lab_production_events(job_id,actor_user_id,actor_role,request_id,request_payload,action,version) values(j.id,null,case when auto then 'policy' else 'photographer' end,p_request_id,payload,case when auto then 'submitted_auto_approved' else 'submitted' end,1);return public.lab_production_receipt(j)||jsonb_build_object('replayed',false);end$$;
create function public.read_lab_production_receipt(p_receipt_hash text) returns jsonb language plpgsql security definer set search_path='' as $$declare j public.lab_production_jobs%rowtype;begin select * into j from public.lab_production_jobs where receipt_hash=p_receipt_hash and receipt_expires_at>now();if not found then raise exception 'PRODUCTION_NOT_FOUND' using errcode='42501';end if;return public.lab_production_receipt(j);end$$;

create function public.act_lab_production_job(p_user_id uuid,p_job_id uuid,p_expected_version integer,p_request_id uuid,p_action text,p_details jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare j public.lab_production_jobs%rowtype;e public.lab_production_events%rowtype;payload jsonb;receiver boolean;owner_actor boolean;idx text;l jsonb;a public.lab_production_assets%rowtype;role_name text;next_status text;begin
 if p_user_id is null or p_request_id is null or p_expected_version is null or p_expected_version<1 or p_action is null or p_action not in('approve_order','accept','approve_crop','complete_colour','final_review','transition') or p_details is null or jsonb_typeof(p_details)<>'object' then raise exception 'PRODUCTION_INVALID' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('production-request:'||p_user_id::text||p_request_id::text,20261016));select * into j from public.lab_production_jobs where id=p_job_id for update;
 if not found or not public.lab_production_reader(p_user_id,j.photographer_id,j.lab_id) then raise exception 'PRODUCTION_NOT_FOUND' using errcode='42501';end if;
 payload:=jsonb_build_object('jobId',p_job_id,'expectedVersion',p_expected_version,'action',p_action,'details',p_details);select * into e from public.lab_production_events where actor_user_id=p_user_id and request_id=p_request_id;
 if found then if e.request_payload is distinct from payload then raise exception 'PRODUCTION_REQUEST_CONFLICT' using errcode='PT409';end if;return to_jsonb(j)||jsonb_build_object('replayed',true);end if;
 if j.version<>p_expected_version then raise exception 'PRODUCTION_VERSION_CONFLICT' using errcode='PT409';end if;
 receiver:=public.lab_production_receiver(p_user_id,j.photographer_id,j.lab_id);owner_actor:=public.lab_production_owner(p_user_id,j.photographer_id);role_name:=case when p_action='approve_order' then 'photographer' else 'lab' end;
 if p_action='approve_order' then
 if not owner_actor or j.status not in('submitted','accepted') or p_details<>'{}'::jsonb then raise exception 'PRODUCTION_FORBIDDEN' using errcode='42501';end if;j.work:=j.work||jsonb_build_object('photographerApproved',true,'photographerApprovedAt',now());
 elsif p_action='accept' then
 if not receiver or j.status<>'submitted' or p_details<>'{}'::jsonb then raise exception 'PRODUCTION_TRANSITION' using errcode='PT409';end if;j.status:='accepted';
 elsif p_action='transition' then
 if not receiver or exists(select 1 from jsonb_object_keys(p_details) k where k<>'status') then raise exception 'PRODUCTION_FORBIDDEN' using errcode='42501';end if;
 next_status:=case j.status when 'accepted' then 'in_production' when 'in_production' then 'ready' when 'ready' then 'completed' else null end;
 if next_status is null or p_details->>'status' is distinct from next_status then raise exception 'PRODUCTION_TRANSITION' using errcode='PT409';end if;
 if public.lab_production_holds(j)<>'[]'::jsonb then raise exception 'PRODUCTION_HELD' using errcode='PT409';end if;j.status:=next_status;
 else
 if p_details->>'size' is null or p_details->>'size' not in('8x10','5x7') or exists(select 1 from jsonb_object_keys(p_details) k where k not in('size','assetId','reviewNoChange')) then raise exception 'PRODUCTION_INVALID' using errcode='22023';end if;
 idx:=case p_details->>'size' when '8x10' then '0' else '1' end;l:=j.work#>array['lines',idx];select * into a from public.lab_production_assets where id=(p_details->>'assetId')::uuid and job_id=j.id and size=p_details->>'size';if not found then raise exception 'PRODUCTION_STALE_RENDER' using errcode='PT409';end if;
 if p_action<>'complete_colour' and p_details ? 'reviewNoChange' then raise exception 'PRODUCTION_INVALID' using errcode='22023';end if;if p_action='approve_crop' then
 if not(owner_actor and j.snapshot#>>'{policy,cropResponsibility}'='photographer') and not(receiver and j.snapshot#>>'{policy,cropResponsibility}'='lab') then raise exception 'PRODUCTION_FORBIDDEN' using errcode='42501';end if;
 if j.status not in('submitted','accepted') or l->>'cropAssetId' is distinct from a.id::text or a.kind<>'crop' then raise exception 'PRODUCTION_STALE_RENDER' using errcode='PT409';end if;
 role_name:=case when j.snapshot#>>'{policy,cropResponsibility}'='photographer' then 'photographer' else 'lab' end;l:=l||jsonb_build_object('cropApproved',true,'cropApprovedAt',now());
 elsif p_action='complete_colour' then
 if not receiver or j.status<>'accepted' or j.snapshot#>>'{policy,labColourCorrection}' is distinct from 'true' then raise exception 'PRODUCTION_FORBIDDEN' using errcode='42501';end if;
 if p_details->'reviewNoChange'='true'::jsonb then if a.kind<>'crop' or a.id::text is distinct from l->>'cropAssetId' then raise exception 'PRODUCTION_STALE_RENDER' using errcode='PT409';end if;else if p_details->'reviewNoChange' is distinct from 'false'::jsonb or a.kind<>'corrected' or a.source_asset_id::text is distinct from l->>'cropAssetId' then raise exception 'PRODUCTION_STALE_RENDER' using errcode='PT409';end if;end if;if l->>'cropApproved' is distinct from 'true' then raise exception 'PRODUCTION_STALE_RENDER' using errcode='PT409';end if;
 l:=(l-'finalReviewedAt')||jsonb_build_object('colourAssetId',a.id,'colourCompletedAt',now());
 else
 if not receiver or j.status<>'accepted' or l->>'cropApproved' is distinct from 'true' or a.id::text is distinct from (case when j.snapshot#>>'{policy,labColourCorrection}'='true' then l->>'colourAssetId' else l->>'cropAssetId' end) then raise exception 'PRODUCTION_STALE_RENDER' using errcode='PT409';end if;l:=l||jsonb_build_object('finalReviewedAt',now());end if;
 j.work:=jsonb_set(j.work,array['lines',idx],l);end if;
 update public.lab_production_jobs set work=j.work,status=j.status,version=version+1,updated_at=now() where id=j.id returning * into j;
 insert into public.lab_production_events(job_id,actor_user_id,actor_role,request_id,request_payload,action,version) values(j.id,p_user_id,role_name,p_request_id,payload,case when p_action='complete_colour' and p_details->'reviewNoChange'='true'::jsonb then 'reviewed_no_colour_change' else p_action end,j.version);return to_jsonb(j)||jsonb_build_object('replayed',false);end$$;

create function public.save_lab_production_crop(p_user_id uuid,p_job_id uuid,p_expected_version integer,p_request_id uuid,p_size text,p_crop jsonb,p_asset_document jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare j public.lab_production_jobs%rowtype;e public.lab_production_events%rowtype;s public.lab_production_assets%rowtype;a jsonb;l jsonb;payload jsonb;idx text;cw integer;ch integer;role_name text;begin
 if p_user_id is null or p_request_id is null or p_expected_version is null or p_expected_version<1 or p_size is null or p_size not in('8x10','5x7') or p_crop is null or jsonb_typeof(p_crop)<>'object' or (select count(*) from jsonb_object_keys(p_crop))<>5 or exists(select 1 from jsonb_object_keys(p_crop) k where k not in('x','y','width','height','rotation')) then raise exception 'PRODUCTION_INVALID_CROP' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('production-request:'||p_user_id::text||p_request_id::text,20261016));select * into j from public.lab_production_jobs where id=p_job_id for update;
 if not found or not public.lab_production_reader(p_user_id,j.photographer_id,j.lab_id) then raise exception 'PRODUCTION_NOT_FOUND' using errcode='42501';end if;
 payload:=jsonb_build_object('jobId',p_job_id,'expectedVersion',p_expected_version,'size',p_size,'crop',p_crop,'asset',p_asset_document);select * into e from public.lab_production_events where actor_user_id=p_user_id and request_id=p_request_id;
 if found then if e.request_payload is distinct from payload then raise exception 'PRODUCTION_REQUEST_CONFLICT' using errcode='PT409';end if;return to_jsonb(j)||jsonb_build_object('replayed',true);end if;
 if j.version<>p_expected_version then raise exception 'PRODUCTION_VERSION_CONFLICT' using errcode='PT409';end if;
 if j.status not in('submitted','accepted') then raise exception 'PRODUCTION_TRANSITION' using errcode='PT409';end if;
 if not(public.lab_production_owner(p_user_id,j.photographer_id) and j.snapshot#>>'{policy,cropResponsibility}'='photographer') and not(public.lab_production_receiver(p_user_id,j.photographer_id,j.lab_id) and j.snapshot#>>'{policy,cropResponsibility}'='lab') then raise exception 'PRODUCTION_FORBIDDEN' using errcode='42501';end if;
 select * into s from public.lab_production_assets where id=(j.snapshot->>'sourceAssetId')::uuid;
 if exists(select 1 from jsonb_each(p_crop) kv where jsonb_typeof(kv.value)<>'number' or (kv.value#>>'{}')::numeric<>trunc((kv.value#>>'{}')::numeric)) then raise exception 'PRODUCTION_INVALID_CROP' using errcode='22023';end if;
 if (p_crop->>'rotation')::integer not in(0,90,180,270) or (p_crop->>'x')::integer<0 or (p_crop->>'y')::integer<0 or (p_crop->>'width')::integer<1 or (p_crop->>'height')::integer<1 then raise exception 'PRODUCTION_INVALID_CROP' using errcode='22023';end if;
 cw:=(p_crop->>'width')::integer;ch:=(p_crop->>'height')::integer;
 if (p_crop->>'x')::bigint+cw>s.width_pixels or (p_crop->>'y')::bigint+ch>s.height_pixels then raise exception 'PRODUCTION_INVALID_CROP' using errcode='22023';end if;
 if (p_crop->>'rotation')::integer in(90,270) then cw:=(p_crop->>'height')::integer;ch:=(p_crop->>'width')::integer;end if;
 if abs((cw::numeric/ch)/(case p_size when '8x10' then 8.0/10 else 5.0/7 end)-1)>0.002 or cw<(case p_size when '8x10' then 1600 else 1000 end) or ch<(case p_size when '8x10' then 2000 else 1400 end) then raise exception 'PRODUCTION_CROP_DETAIL' using errcode='22023';end if;
 if p_asset_document->>'kind' is distinct from 'crop' or p_asset_document->>'jobId' is distinct from j.id::text or p_asset_document->>'size' is distinct from p_size then raise exception 'PRODUCTION_INVALID_ASSET' using errcode='22023';end if;
 a:=public.register_lab_production_asset(p_user_id,p_asset_document);idx:=case p_size when '8x10' then '0' else '1' end;
 l:=(j.work#>array['lines',idx])-'colourAssetId'-'colourCompletedAt'-'finalReviewedAt'-'cropApprovedAt';l:=l||jsonb_build_object('crop',p_crop,'cropAssetId',a->>'id','cropApproved',false);
 update public.lab_production_jobs set work=jsonb_set(j.work,array['lines',idx],l),version=version+1,updated_at=now() where id=j.id returning * into j;
 role_name:=case when j.snapshot#>>'{policy,cropResponsibility}'='photographer' then 'photographer' else 'lab' end;
 insert into public.lab_production_events(job_id,actor_user_id,actor_role,request_id,request_payload,action,version) values(j.id,p_user_id,role_name,p_request_id,payload,'save_crop',j.version);return to_jsonb(j)||jsonb_build_object('replayed',false);end$$;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('lab-production-workflow-files','lab-production-workflow-files',false,4000000,array['image/jpeg','image/png']) on conflict(id) do nothing;
-- Original and render bytes are accessible only through the checked server routes.
-- No anonymous/client storage-object read or write policy is introduced.
do $$declare r record;begin for r in select p.oid::regprocedure as signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like '%lab_production%' or p.proname='protect_lab_production') loop
 execute format('revoke all on function %s from public,anon,authenticated',r.signature);
 if r.proname in('save_lab_production_policy','register_lab_production_asset','create_lab_production_gallery','manage_lab_production_gallery','read_lab_production_gallery','read_lab_production_photo','submit_lab_production_order','read_lab_production_receipt','act_lab_production_job','save_lab_production_crop') then execute format('grant execute on function %s to service_role',r.signature);
 elsif r.proname in('lab_production_owner','lab_production_reader','lab_production_receiver','lab_production_file_reader') then execute format('grant execute on function %s to authenticated,service_role',r.signature);end if;end loop;end$$;
commit;
